1	// Module customer-action, key: the order id. Owns R3.1 (action-required within 120 min of clearing), R3.2 (the
2	// customer's deadline D = p + customerActionHours; the first amend or cancel at or before D counts; a timeout after D)
3	// and S1. Calls statuses and notices. Wake-up: `deadline` at D + 30 min (after D, so an action at D still wins; well
4	// inside the window (D, D + 60 min]).
5	//
6	// It starts when the order is recorded, so that an amend that arrives during the fraud review is still judged in time
7	// (R3.2 counts an action at or before D whatever the review state); R3.1 waits for the clearing.
8	//
9	// state: { phase, orderId, placedAt, deadline, unavailable: [fid], available: [fid], at, reason }
10	//   phase: 'inert' (nothing unavailable) | 'review' (recorded, not cleared) | 'waiting' (action-required sent) |
11	//          'amended' (counted amend during review) | 'ready' (counted amend, ready at `at`) | 'cancel' | 'timedOut' |
12	//          'stopped'
13	
14	const WAKE_AFTER_MIN = 30;
15	
16	// Files arrive as raw text: parse a JSON file (or pass a parsed value through).
17	function fileJson(files, path) {
18	  const v = files?.[path];
19	  return typeof v === 'string' ? JSON.parse(v) : v ?? null;
20	}
21	
22	export function step(input, ctx) {
23	  switch (input.op) {
24	    case 'start': return start(input, ctx);
25	    case 'advance': return advance(input, ctx);
26	    case 'action': return action(input, ctx);
27	    case 'stop': return stop(input, ctx);
28	    case 'resume': return resume(input, ctx);
29	  }
30	  throw new Error(`customer-action: unknown op ${input.op}`);
31	}
32	
33	export function onEvent(event, ctx) {
34	  if (event.type === 'timer.fired' && ctx.state && (ctx.state.phase === 'review' || ctx.state.phase === 'waiting')) {
35	    return timedOut(ctx.state, ctx);
36	  }
37	  return { output: view(ctx.state) };
38	}
39	
40	function view(state) {
41	  if (!state) return { state: 'idle', at: null, reason: null, busy: false };
42	  return {
43	    state: state.phase, at: state.at ?? null, reason: state.reason ?? null,
44	    busy: state.phase === 'review' || state.phase === 'waiting',
45	  };
46	}
47	
48	function start(input, ctx) {
49	  const unavailable = input.fulfilments.filter(f => !f.available).map(f => f.fulfilmentId);
50	  const available = input.fulfilments.filter(f => f.available).map(f => f.fulfilmentId);
51	  const deadline = addMinutes(input.placedAt, policyOf(input, ctx).customerActionHours * 60);     // R3.2, S1: from p
52	  if (unavailable.length === 0) {
53	    const state = { phase: 'inert', orderId: input.orderId, placedAt: input.placedAt, deadline, unavailable, available, at: null, reason: null };
54	    return { output: view(state), state };
55	  }
56	  const state = { phase: 'review', orderId: input.orderId, placedAt: input.placedAt, deadline, unavailable, available, at: null, reason: null };
57	  return { output: view(state), state, obligations: { upsert: [wakeUp(deadline)] } };
58	}
59	
60	function advance(input, ctx) {
61	  const state = ctx.state;
62	  if (state && state.phase === 'amended') {
63	    // Counted during the review (R3.2): the order is ready when it clears; R3.1 is moot (S9).
64	    const next = { ...state, phase: 'ready' };
65	    return { output: view(next), state: next };
66	  }
67	  if (!state || state.phase !== 'review') return { output: view(state) };
68	  // The order is cleared now (R3.1): action-required, within 120 min of the clearing.
69	  const orderId = state.orderId;
70	  const next = { ...state, phase: 'waiting', at: input.clearedAt ?? null };
71	  ctx.call('statuses', orderId, { op: 'set', orderId, fulfilmentId: null, status: 'customerActionRequired' });
72	  ctx.call('notices', orderId, { op: 'send', template: 'action-required', about: orderId });
73	  return { output: view(next), state: next };
74	}
75	
76	function action(input, ctx) {
77	  const state = ctx.state;
78	  if (!state || (state.phase !== 'review' && state.phase !== 'waiting')) return { output: view(state) };
79	  // The first amend or cancel at or before D counts (R3.2). Later actions change nothing.
80	  if (Date.parse(input.at) > Date.parse(state.deadline)) return { output: view(state) };
81	  const orderId = state.orderId;
82	  if (input.action === 'cancel') {
83	    const next = { ...state, phase: 'cancel', at: input.at, reason: 'customer' };
84	    return { output: view(next), state: next, obligations: { cancel: ['deadline'] } };
85	  }
86	  if (input.action !== 'amend') return { output: view(state) };
87	  // amend: every unavailable fulfilment cancelled within 60 min of the amend (R3.2). S5: nothing when none is unavailable.
88	  if (state.unavailable.length === 0) return { output: view(state) };
89	  for (const fid of state.unavailable) {
90	    ctx.call('statuses', orderId, { op: 'set', orderId, fulfilmentId: fid, status: 'cancelled' });
91	  }
92	  const obligations = { cancel: ['deadline'] };
93	  if (state.available.length === 0) {
94	    const next = { ...state, phase: 'cancel', at: input.at, reason: 'nothing-available' };
95	    return { output: view(next), state: next, obligations };
96	  }
97	  const next = { ...state, phase: state.phase === 'waiting' ? 'ready' : 'amended', at: input.at };
98	  return { output: view(next), state: next, obligations };
99	}
100	
101	function timedOut(state, ctx) {
102	  // Nothing counted by D: after D, within 60 min of D: every fulfilment cancelled, the order timedOut (R3.2).
103	  const orderId = state.orderId;
104	  const all = [...state.unavailable, ...state.available];
105	  for (const fid of all) ctx.call('statuses', orderId, { op: 'set', orderId, fulfilmentId: fid, status: 'cancelled' });
106	  ctx.call('statuses', orderId, { op: 'set', orderId, fulfilmentId: null, status: 'timedOut' });
107	  ctx.call('notices', orderId, { op: 'send', template: 'order-timed-out', about: orderId });
108	  const next = { ...state, phase: 'timedOut', at: ctx.now };
109	  return { output: view(next), state: next };
110	}
111	
112	function stop(input, ctx) {
113	  // A counted cancel elsewhere (R6.2, R6.1, a fraud decision) ends the order: no timeout may fire any more.
114	  if (!ctx.state) return { output: view({ phase: 'stopped' }) };
115	  const had = ctx.state.phase === 'review' || ctx.state.phase === 'waiting';
116	  const next = { ...ctx.state, phase: 'stopped' };
117	  return { output: view(next), state: next, ...(had ? { obligations: { cancel: ['deadline'] } } : {}) };
118	}
119	
120	function resume(input, ctx) {
121	  // §3.5: from the migrated records: a waiting order keeps its deadline; an order not yet cleared is in review.
122	  const r = input.records ?? {};
